585	// the historical-evidence contract. Ranking by mode: search is BM25 (substring
586	// scorer as fallback); query fuses BM25 with calibrated conversation vectors
587	// when the gated semantic arm is available and degrades to exactly the lexical
588	// ranking otherwise; vsearch is semantic-only and returns a structured
589	// unavailable error when the arm is closed.
590	func retrieveConversation(brainDir, query string, limit int, mode retrievalMode, opts retrievalOptions) ([]unifiedResult, error) {
591		manifest, err := loadBrainManifest(brainDir)
592		if err != nil {
593			return nil, err
594		}
595		if manifest.Sources == nil || manifest.Sources.History == nil {
596			if mode == modeVector {
597				return nil, errConversationVectorUnsupported
598			}
599			return nil, nil
600		}
601		fresh, err := loadFreshHistory(brainDir, manifest.Sources.History)
602		if err != nil {
603			return nil, fmt.Errorf("load history index: %w", err)
604		}
605		filtered := opts.hasConversationOnlyFilters() || strings.TrimSpace(opts.Branch) != ""
606		// Filters and the diversity cap discard ranked candidates, so over-fetch
607		// enough for the survivors to still fill the limit.
608		candidateLimit := limit * 4
609		if filtered {
610			candidateLimit = limit * 16
611		}
612		if candidateLimit < limit { // overflow guard
613			candidateLimit = limit
614		}
615		var scored []scoredHistoryRecord
616		switch mode {
617		case modeVector:
618			scores := conversationSemanticScores(brainDir, historySemanticEmbedder(defaultEmbedder()), query, candidateLimit, false)
619			if len(scores) == 0 {
620				return nil, errConversationVectorUnsupported
621			}
622			// Semantic-only ranks long-term vectors; short-term records have no
623			// vectors until consolidation and are deliberately absent here.
624			scored = rankConversationSemantic(fresh.longTermActive(), scores, candidateLimit)
625		case modeHybrid:
626			// Conversation fusion is OFF by default pending a validated positive:
627			// the 2026-08-07 calibration on the entire-brain corpus (22-task exact
628			// pack + 10-task paraphrase stratum, EmbeddingGemma) measured fusion
629			// trading exact-match precision (R@1 0.864→0.773, one R@5 loss, one
630			// paraphrase dropped from rank 1 to unranked) for +1 paraphrase hit;
631			// the same displacement failure mode that closed Model2Vec history
632			// fusion. Same discipline as historyFusionEligible: the fused arm
633			// ships dark behind a development flag until an eval-ledger row
634			// validates it (see docs/eval_ledger.md).
635			scored = rankFreshHistory(fresh, conversationKind, query, candidateLimit, func(longTerm historyIndex) ([]scoredHistoryRecord, bool) {
636				if envBool("ENTIRE_BRAIN_CONVERSATION_FUSION") {
637					return rankConversationFused(brainDir, longTerm, query, candidateLimit, defaultEmbedder())
638				}
639				return rankHistoryViaFTS(brainDir, longTerm, conversationKind, query, candidateLimit)
640			})
641		default:
642			scored = rankFreshHistory(fresh, conversationKind, query, candidateLimit, func(longTerm historyIndex) ([]scoredHistoryRecord, bool) {
643				return rankHistoryViaFTS(brainDir, longTerm, conversationKind, query, candidateLimit)
644			})
645		}
646		kept := make([]scoredHistoryRecord, 0, len(scored))
647		for _, s := range scored {
648			if conversationRecordMatchesFilters(s.Record, opts) {
649				kept = append(kept, s)
650			}
651		}
652		kept = capConversationSessionShare(kept, limit, opts)
653		if len(kept) > limit {
654			kept = kept[:limit]
655		}
656		out := make([]unifiedResult, len(kept))
657		for i, s := range kept {
658			out[i] = conversationToUnified(s.Record)
659			// Explainability: which query tokens actually hit this record, so a
660			// thin result is debuggable ("only 'bug' matched") instead of opaque.
661			out[i].MatchedTerms = historyRecordMatchedTerms(s.Record, query)
662			// Preserve list order for callers that read Score; RRF-scale for
663			// consistency with single-list merges.
664			out[i].Score = 1.0 / (rrfK + float64(i+1))
665		}
666		return out, nil
667	}
668	
669	// conversationRecordMatchesFilters applies the structured conversation filters.
670	// Scope safety over recall: a record that cannot prove it is inside a time
671	// filter (no session time) is excluded when one is set.
672	func conversationRecordMatchesFilters(record historyRecord, opts retrievalOptions) bool {
673		if session := strings.TrimSpace(opts.SessionID); session != "" && record.SessionID != session {
674			return false
675		}
676		if agent := strings.TrimSpace(opts.Agent); agent != "" && !strings.EqualFold(record.Agent, agent) {
677			return false
678		}
679		if branch := strings.TrimSpace(opts.Branch); branch != "" && record.Branch != branch {
680			return false
681		}
682		if !opts.After.IsZero() || !opts.Before.IsZero() {
683			created, err := time.Parse(time.RFC3339, record.CreatedAt)
684			if err != nil {
685				return false
686			}
687			if !opts.After.IsZero() && created.Before(opts.After) {
688				return false
689			}
690			if !opts.Before.IsZero() && !created.Before(opts.Before) {
691				return false
692			}
693		}
694		return true
695	}
696	
697	// capConversationSessionShare enforces the per-session diversity cap: at most
698	// max(1, limit/conversationSessionTopKDivisor) results per session while other
699	// sessions still have candidates. If the cap leaves the list short and only
700	// capped sessions have candidates left, they backfill in rank order; the cap
701	// prevents crowding out, it does not hide the only matching session. An
702	// explicit session filter disables the cap entirely.
703	func capConversationSessionShare(scored []scoredHistoryRecord, limit int, opts retrievalOptions) []scoredHistoryRecord {
704		if strings.TrimSpace(opts.SessionID) != "" || len(scored) <= 1 {
