// build, so callers can branch on "why" — gate vs build — for messaging.
func historyVectorStoreFor(brainDir string, e Embedder) (historyVectorStore, bool) {
	if e == nil {
		return nil, false
	}
	return newHistoryVectorStore(brainDir, e.ID(), e.Dim())
